findings.suggestion:
按 EXPECTED_TYPES 做校验并给出明确错误（必要时做安全转换）：

for key, typ in EXPECTED_TYPES.items():
    if key not in config:
        raise ConfigError("缺少配置项 %s" % key)
    value = config[key]
    if typ is bool and not isinstance(value, bool):
        raise ConfigError("%s 应为 bool，实际 %r" % (key, value))
    if typ is int and isinstance(value, bool):
        raise ConfigError("%s 应为 int，不应为 bool" % key)
    if not isinstance(value, typ):
        raise ConfigError("%s 应为 %s，实际 %r" % (key, typ.__name__, value))
    result[key] = value

